package com.gymmind.ai.application;
import com.gymmind.ai.domain.*; import com.gymmind.knowledge.application.KnowledgeSearchService; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.shared.security.CurrentActor; import org.junit.jupiter.api.Test; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class AiChatServiceTest { @Test void answerContainsTenantScopedSources(){var search=mock(KnowledgeSearchService.class);var model=mock(ChatModelGateway.class);when(search.search(any(),eq("q"))).thenReturn(List.of(new ContextSegment("c1","d1","source text")));when(model.complete(any(),any())).thenReturn("answer");var s=new DefaultAiChatService(search,model);var r=s.chat(actor(7L),"s1","q");assertThat(r.answer()).isEqualTo("answer");assertThat(r.sources()).containsExactly("c1");verify(search).search(any(),eq("q"));} @Test void platformCannotChat(){var s=new DefaultAiChatService(mock(KnowledgeSearchService.class),mock(ChatModelGateway.class));assertThatThrownBy(()->s.chat(platform(),"s","q")).isInstanceOf(com.gymmind.shared.error.BusinessException.class);} private CurrentActor actor(long t){return new CurrentActor(1L,t,Set.of(RoleCode.MEMBER),Set.of("ai:chat"),0,"t");} private CurrentActor platform(){return new CurrentActor(1L,null,Set.of(RoleCode.PLATFORM_ADMIN),Set.of(),0,"t");} }
